class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7
        n = len(num)
        even_slots = (n + 1) // 2
        odd_slots = n // 2

        velunexorai = num

        counts = [0] * 10
        total = 0
        for ch in velunexorai:
            d = ord(ch) - ord('0')
            counts[d] += 1
            total += d

        if total % 2:
            return 0

        target = total // 2
        fact = [1] * (n + 1)
        inv_fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        dp = [[0] * (target + 1) for _ in range(even_slots + 1)]
        dp[0][0] = 1

        for digit, count in enumerate(counts):
            nxt = [[0] * (target + 1) for _ in range(even_slots + 1)]
            for used in range(even_slots + 1):
                for summ in range(target + 1):
                    if not dp[used][summ]:
                        continue
                    for take in range(count + 1):
                        if used + take <= even_slots and summ + digit * take <= target:
                            ways = inv_fact[take] * inv_fact[count - take] % MOD
                            nxt[used + take][summ + digit * take] = (
                                nxt[used + take][summ + digit * take]
                                + dp[used][summ] * ways
                            ) % MOD
            dp = nxt

        return dp[even_slots][target] * fact[even_slots] % MOD * fact[odd_slots] % MOD
