def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    edges = [(ord(s[0]) - 65, ord(s[1]) - 65) for s in data[1:]]

    g = [[] for _ in range(26)]
    rg = [[] for _ in range(26)]
    for u, v in edges:
        g[u].append(v)
        rg[v].append(u)

    seen = [False] * 26
    order = []

    def dfs(v):
        seen[v] = True
        for to in g[v]:
            if not seen[to]:
                dfs(to)
        order.append(v)

    for v in range(26):
        if not seen[v]:
            dfs(v)

    comp = [-1] * 26

    def rdfs(v, c):
        comp[v] = c
        for to in rg[v]:
            if comp[to] == -1:
                rdfs(to, c)

    cnum = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cnum)
            cnum += 1

    cross = []
    internal = [False] * cnum
    incident = [False] * cnum

    for u, v in edges:
        a, b = comp[u], comp[v]
        if a == b:
            internal[a] = True
        else:
            cross.append((a, b))
            incident[a] = incident[b] = True

    reach = [[False] * cnum for _ in range(cnum)]
    for i in range(cnum):
        reach[i][i] = True
    for a, b in cross:
        reach[a][b] = True

    for k in range(cnum):
        for i in range(cnum):
            if reach[i][k]:
                for j in range(cnum):
                    reach[i][j] |= reach[k][j]

    m = len(cross)
    adj = [[] for _ in range(m)]
    for i, (_, to) in enumerate(cross):
        for j, (fr, _) in enumerate(cross):
            if reach[to][fr]:
                adj[i].append(j)

    match_r = [-1] * m

    def augment(v, used):
        for to in adj[v]:
            if used[to]:
                continue
            used[to] = True
            if match_r[to] == -1 or augment(match_r[to], used):
                match_r[to] = v
                return True
        return False

    matching = 0
    for i in range(m):
        if augment(i, [False] * m):
            matching += 1

    answer = m - matching
    for c in range(cnum):
        if internal[c] and not incident[c]:
            answer += 1

    print(answer)

if __name__ == "__main__":
    main()
